!function(a){a.behaviors.calendarList={attach:function(a){a.querySelectorAll("[data-calendar-list-result]").forEach((function(t){var e='td[data-calendar-view-day="'+t.getAttribute("data-calendar-view-day")+'"][data-calendar-view-month="'+t.getAttribute("data-calendar-view-month")+'"]';a.querySelectorAll(e).length<1&&t.setAttribute("data-calendar-list-result","hidden")}))}}}(Drupal);